<?php require 'includes/bootstrap.php';$token=$_GET['token']??'';$ok=false;if(preg_match('/^[a-f0-9]{64}$/',$token)){$s=$pdo->prepare('SELECT id FROM users WHERE verify_hash=? AND verify_expires>NOW() AND verified_at IS NULL');$s->execute([hash('sha256',$token)]);if($u=$s->fetch()){$pdo->prepare('UPDATE users SET verified_at=NOW(),verify_hash=NULL,verify_expires=NULL WHERE id=?')->execute([$u['id']]);audit('email_verified',(int)$u['id']);$ok=true;}}$pageTitle='Email verification';require 'includes/header.php';?><section class="card narrow"><h1><?=$ok?'Email verified':'Link invalid or expired'?></h1><p><?=$ok?'Your account is ready.':'Request a new registration or contact the administrator.'?></p><a class="button" href="login.php">Go to login</a></section><?php require 'includes/footer.php';?>
